ode (b) at (0,-2) {$\pt{B}$}; 
ode (b1) at (2,-1.4) {$ lank$}; 
ode (b2) at (4,-1.4) {$\pt{B}$}; 
ode (b3) at (2,-2.6) {$\pt{B}$}; 
